pragma solidity ^0.8.0;

import "forge-std/Test.sol";

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xDeEa8fdB85503531F6A5D2A036d3268bD7C06c09;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for storage manipulation
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Calculate storage slot for _owner (slot 0)
        bytes32 ownerSlot = bytes32(uint256(0));

        // Step 2: Write our address to the owner slot
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Step 3: Call renounceOwnership() as the new owner
        vm.prank(attacker);
        (bool success, ) = TARGET.call(abi.encodeWithSignature("renounceOwnership()"));
        require(success, "renounceOwnership failed");

        // Step 4: Verify owner is now address(0)
        (bool success2, bytes memory data) = TARGET.staticcall(abi.encodeWithSignature("owner()"));
        require(success2, "owner() call failed");
        address currentOwner = abi.decode(data, (address));
        assertEq(currentOwner, address(0), "Owner should be zero address");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

